mapper.select:
SELECT COUNT(*)
FROM notice
WHERE target_board = #{targetBoard}

mapper.update:
UPDATE notice
SET views = views + 1
WHERE notice_id = #{noticeId}

UPDATE notice
SET title = #{request.title}, content = #{request.content}, updated_at = NOW()
WHERE notice_id = #{noticeId}

UPDATE notice
SET is_active = 0, is_pinned = 0
WHERE notice_id = #{noticeId}

UPDATE notice
SET is_pinned = #{isPinned}
WHERE notice_id = #{noticeId}
AND is_active = 1

mapper.select:
SELECT target_board
FROM notice
WHERE notice_id = #{noticeId}
